    if (['at_query','at_get','business_schema'].includes(name)&&typeof a.entity==='string') assertEntityArea(p,a.entity);
    if(name==='work_write_options')assertArea(p,a.kind==='expenses'?'expenses':a.kind==='time_off'?'scheduling':'time');
